const calculateFactorial = n => {
  const isBaseCase = val => val === 0;
  const multiply = (a, b) => a * b;
  const decrement = x => x - 1;
  const iterativeFactorial = (currentN, accumulator) =>
    isBaseCase(currentN) ? accumulator : iterativeFactorial(decrement(currentN), multiply(accumulator, currentN));
  const isNonNegativeInteger = num => Number.isInteger(num) && num >= 0;

  if (!isNonNegativeInteger(n)) {
    throw new Error('Input must be a non-negative integer.');
  }

  return iterativeFactorial(n, 1);
};

