  const iterativeFactorial = function(currentN, accumulator) {
    return isBaseCase(currentN) ? accumulator : iterativeFactorial(decrement(currentN), multiply(accumulator, currentN));
  };
  const isNonNegativeInteger = function(num) { return Number.isInteger(num) && num >= 0; };

  if (!isNonNegativeInteger(n)) {
    throw new Error('Input must be a non-negative integer.');
  }

  return iterativeFactorial(n, 1);
};

