const generateFibonacci = n => {
  if (n <= 0) return [];
  if (n === 1) return [0];

  const sequence = [0, 1];
  const appendNext = (arr, i) => {
    const next = arr[i - 1] + arr[i - 2];
    arr.push(next);
    return arr;
  };

  for (let i = 2; i < n; i++) {
    appendNext(sequence, i);
  }

  const mapToNumber = x => x;
  return sequence.map(mapToNumber);
};

const getFirstElement = arr => arr[0];
const getLastElement = arr => arr[arr.length - 1];
const sumArray = arr => arr.reduce((acc, val) => acc + val, 0);

const testFibonacci = n => {
  const result = generateFibonacci(n);
  console.log(`Fibonacci(${n}): ${result}`);
  console.log(`First element: ${getFirstElement(result)}`);
  console.log(`Last element: ${getLastElement(result)}`);
  console.log(`Sum of elements: ${sumArray(result)}`);
};

