const removeDuplicates = (arr) => {
  const seenElements = {};
  const addIfNew = (element) => {
    if (!seenElements[element]) {
      seenElements[element] = true;
      return true;
    }
    return false;
  };
  const filterElements = (element) => addIfNew(element);
  const result = arr.filter(filterElements);
  return result;
};

