const isPrime = num => {
  if (num <= 1) return false;

  const isDivisible = (n, divisor) => n % divisor === 0;

  const checkDivisors = (n, start) => {
    if (start * start > n) return true;
    return isDivisible(n, start) ? false : checkDivisors(n, start + 1);
  };

  return checkDivisors(num, 2);
};

const mapNumbers = (arr, func) => arr.map(func);

const filterPrimes = numbers => numbers.filter(n => isPrime(n));

const getSum = numbers => numbers.reduce((acc, current) => acc + current, 0);

const processNumbers = nums => {
  const doubled = mapNumbers(nums, x => x * 2);
  const primes = filterPrimes(doubled);
  return getSum(primes);
};

