const calculateAge = birthdateStr => {
  const birthDate = new Date(birthdateStr);
  const today = new Date();

  const getFullYear = date => date.getFullYear();
  const getMonth = date => date.getMonth();
  const getDate = date => date.getDate();

  let age = getFullYear(today) - getFullYear(birthDate);

  const monthDiff = getMonth(today) - getMonth(birthDate);
  const dayDiff = getDate(today) - getDate(birthDate);

  const adjustAge = (diffMonth, diffDay, currentAge) => {
    if (diffMonth < 0 || (diffMonth === 0 && diffDay < 0)) {
      return currentAge - 1;
    }
    return currentAge;
  };

  return adjustAge(monthDiff, dayDiff, age);
};

const getAgeInYears = birthdate => calculateAge(birthdate);

const printAge = birthdate => console.log(`Age for ${birthdate}: ${getAgeInYears(birthdate)}`);

