const addItemToInventory = function(inventory, item, quantity) {
  const updateItem = function(currentInventory, itemName, qtyToAdd) {
    return {
      ...currentInventory,
      [itemName]: (currentInventory[itemName] || 0) + qtyToAdd,
    };
  };

  const hasItem = function(inv, itm) {
    return Object.prototype.hasOwnProperty.call(inv, itm);
  };

  const createNewInventory = function(inv, itm, qty) {
    return { ...inv, [itm]: qty };
  };

  const processAddition = function(inv, itm, qty) {
    return hasItem(inv, itm) ? updateItem(inv, itm, qty) : createNewInventory(inv, itm, qty);
  };

  const applyQuantity = function(inv, itm, qty) {
    return processAddition(inv, itm, qty);
  };

  return applyQuantity(inventory, item, quantity);
};

const getInventoryKeys = function(inventory) {
  return Object.keys(inventory);
};

const getTotalItems = function(inventory) {
  return getInventoryKeys(inventory).reduce(function(acc, key) {
    return acc + inventory[key];
  }, 0);
};

const isInventoryEmpty = function(inventory) {
  return getInventoryKeys(inventory).length === 0;
};

