const choices = ['rock', 'paper', 'scissors'];

const getRandomChoice = () => choices[Math.floor(Math.random() * choices.length)];

const getResult = (player, computer) => {
    if (player === computer) return 'Tie';
    if (
        (player === 'rock' && computer === 'scissors') ||
        (player === 'paper' && computer === 'rock') ||
        (player === 'scissors' && computer === 'paper')
    ) {
        return 'Win';
    }
    return 'Loss';
};

const validateChoice = choice => choices.includes(choice);

const playRockPaperScissors = playerChoice => {
    if (!validateChoice(playerChoice)) {
        throw new Error('Invalid player choice');
    }
    const computerChoice = getRandomChoice();
    return getResult(playerChoice, computerChoice);
};

