const extractEmails = text => {
  const emailRegex = /[\w.-]+@([\w-]+\.)+[\w-]{2,4}/g;
  const findMatches = str => str.match(emailRegex);
  const filterNull = arr => arr ? arr.filter(Boolean) : [];
  const removeDuplicates = arr => [...new Set(arr)];
  const toLowerCase = arr => arr.map(email => email.toLowerCase());
  const processEmails = str => toLowerCase(removeDuplicates(filterNull(findMatches(str))));
  return processEmails(text);
};

