const startsWith = (str, prefix) => {
  const getLength = s => s.length;
  const strLength = getLength(str);
  const prefixLength = getLength(prefix);

  if (prefixLength > strLength) {
    return false;
  }

  const getChar = (s, i) => s[i];
  const compareChars = (char1, char2) => char1 === char2;

  for (let i = 0; i < prefixLength; i++) {
    const charFromStr = getChar(str, i);
    const charFromPrefix = getChar(prefix, i);
    if (!compareChars(charFromStr, charFromPrefix)) {
      return false;
    }
  }
  return true;
};

