const romanToInt = roman => {
  const values = {
    I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000
  };

  const toArray = str => [...str];

  const mapToNumeric = arr => arr.map(char => values[char]);

  const calculateSum = (acc, num, index, arr) => {
    const nextNum = arr[index + 1];
    return acc + (nextNum > num ? -num : num);
  };

  const processArray = numericArray =>
    numericArray.reduce(calculateSum, 0);

  const reverseAndSum = arr =>
    arr.reverse().reduce((sum, num, i, a) => {
      const prev = a[i - 1] || 0;
      return sum + (num < prev ? -num : num);
    }, 0);

  const numeric = mapToNumeric(toArray(roman));
  return reverseAndSum(numeric);
};

