const findMissingNumber = nums => {
  const n = nums.length;
  const expectedSum = n * (n + 1) / 2;

  const actualSum = nums.reduce((acc, current) => acc + current, 0);

  const calculateDifference = (expected, actual) => expected - actual;

  const isPositive = num => num >= 0;

  const getResult = (diff, isValid) => isValid ? diff : -1;

  const missing = calculateDifference(expectedSum, actualSum);

  const isValidResult = isPositive(missing);

  return getResult(missing, isValidResult);
};

