const caesarCipher = (text, shift) => {
  const normalizeShift = s => s % 26;
  const isLetter = char => /[a-zA-Z]/.test(char);
  const getBaseCode = char => char === char.toLowerCase() ? 97 : 65;
  const encryptChar = (char, s) => {
    if (!isLetter(char)) return char;
    const base = getBaseCode(char);
    const offset = char.charCodeAt(0) - base;
    const newOffset = (offset + s + 26) % 26;
    return String.fromCharCode(base + newOffset);
  };
  const effectiveShift = normalizeShift(shift);
  return Array.from(text).map(char => encryptChar(char, effectiveShift)).join('');
};

