const isValidParentheses = s => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  const isOpenBracket = char => map.hasOwnProperty(char);
  const isMatchingPair = (open, close) => map[open] === close;

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    if (isOpenBracket(char)) {
      stack.push(char);
    } else {
      if (stack.length === 0) return false;
      const lastOpen = stack.pop();
      if (!isMatchingPair(lastOpen, char)) return false;
    }
  }

  return stack.length === 0;
};

