const decimalToBinary = decimalNum => {
  if (decimalNum === 0) return '0';

  let binaryString = '';
  let currentNum = decimalNum;

  const appendBit = (str, bit) => bit + str;
  const isEven = num => num % 2 === 0;
  const getRemainder = num => num % 2;
  const divideByTwo = num => Math.floor(num / 2);

  while (currentNum > 0) {
    const remainder = getRemainder(currentNum);
