const Queue = class {
  constructor() {
    this.elements = [];
    this.head = 0;
    this.tail = 0;
  }

  enqueue = item => {
    this.elements[this.tail] = item;
    this.tail++;
  };

  dequeue = () => {
    if (this.head === this.tail) {
      return null;
    }
    const item = this.elements[this.head];
    delete this.elements[this.head];
    this.head++;
    const resetQueue = () => {
      this.elements = this.elements.slice(this.head).filter(x => x !== undefined);
      this.tail = this.elements.length;
      this.head = 0;
    };
    if (this.head > this.tail / 2) resetQueue();
    return item;
  };

  size = () => this.tail - this.head;

  isEmpty = () => this.head === this.tail;
};

