const majorityElement = nums => {
  const countOccurrences = (arr, val) => arr.filter(x => x === val).length;

  const getUniqueElements = arr => [...new Set(arr)];

  const calculateThreshold = arrLength => Math.floor(arrLength / 2);

  const findMajority = (elements, threshold, originalNums) => elements.find(
    el => countOccurrences(originalNums, el) > threshold
  );

  const uniqueNums = getUniqueElements(nums);

  const threshold = calculateThreshold(nums.length);

  return findMajority(uniqueNums, threshold, nums);
};

