const stringPermutations = (str) => {
  const chars = str.split('');

  const generatePermutations = (arr) => {
    if (arr.length === 0) return [''];
    if (arr.length === 1) return arr;

    return arr.flatMap((char, i) => {
      const remainingChars = [...arr.slice(0, i), ...arr.slice(i + 1)];
      return generatePermutations(remainingChars).map(perm => char + perm);
    });
  };

  const allPerms = generatePermutations(chars);
  const uniquePerms = [...new Set(allPerms)];
  return uniquePerms;
};

