const findAllDivisors = n => {
  const isDivisible = (num, divisor) => num % divisor === 0;
  const generateRange = limit => Array.from({ length: limit }, (_, i) => i + 1);

  const filterDivisors = (num, possibleDivisors) =>
    possibleDivisors.filter(d => isDivisible(num, d));

  const getHalfPoint = num => Math.floor(Math.sqrt(num));

  const getDivisorsUpToHalf = num =>
    filterDivisors(num, generateRange(getHalfPoint(num)));

  const getComplementaryDivisors = (num, smallDivisors) =>
    smallDivisors
      .filter(d => d * d !== num)
      .map(d => num / d)
      .reverse();

  const smallDivs = getDivisorsUpToHalf(n);
  const largeDivs = getComplementaryDivisors(n, smallDivs);

  return [...smallDivs, ...largeDivs];
};

