const calculateMean = numbers => numbers.reduce((sum, num) => sum + num, 0) / numbers.length;

const calculateSquaredDifference = (num, mean) => (num - mean) ** 2;

const calculateSumOfSquaredDifferences = (numbers, mean) =>
  numbers.map(num => calculateSquaredDifference(num, mean))
         .reduce((sum, sqDiff) => sum + sqDiff, 0);

const calculateVariance = (sumOfSquaredDifferences, count) => sumOfSquaredDifferences / (count - 1);

const calculateStandardDeviation = numbers => {
  if (numbers.length < 2) return 0;

  const mean = calculateMean(numbers);
  const sumSqDiff = calculateSumOfSquaredDifferences(numbers, mean);
  const variance = calculateVariance(sumSqDiff, numbers.length);
  return Math.sqrt(variance);
};

