const rotateArray = (nums, k) => {
  const n = nums.length;
  const effectiveK = k % n;

  const reverse = (arr, start, end) => {
    while (start < end) {
      [arr[start], arr[end]] = [arr[end], arr[start]];
      start++;
      end--;
    }
  };

  const fullReverse = arr => reverse(arr, 0, n - 1);
  const firstPartReverse = arr => reverse(arr, 0, effectiveK - 1);
  const secondPartReverse = arr => reverse(arr, effectiveK, n - 1);

