const rotateArray = function(nums, k) {
  const n = nums.length;
  const effectiveK = k % n;

  const reverse = function(arr, start, end) {
    while (start < end) {
      [arr[start], arr[end]] = [arr[end], arr[start]];
      start++;
      end--;
    }
  };

  const fullReverse = function(arr) { return reverse(arr, 0, n - 1); };
  const firstPartReverse = function(arr) { return reverse(arr, 0, effectiveK - 1); };
  const secondPartReverse = function(arr) { return reverse(arr, effectiveK, n - 1); };

  fullReverse(nums);
  firstPartReverse(nums);
  secondPartReverse(nums);

  return nums;
};

