const longestPalindromeSubstring = s => {
  if (s.length < 2) return s;

  let longest = '';

  const expandAroundCenter = (left, right) => {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      left--;
      right++;
    }
    return s.substring(left + 1, right);
  };

  for (let i = 0; i < s.length; i++) {
    const oddPalindrome = expandAroundCenter(i, i);
    const evenPalindrome = expandAroundCenter(i, i + 1);

    if (oddPalindrome.length > longest.length) longest = oddPalindrome;
    if (evenPalindrome.length > longest.length) longest = evenPalindrome;
  }

  const findLongest = (p1, p2) => (p1.length > p2.length ? p1 : p2);

  return Array.from({
    length: s.length
  }, (_, i) => i)
    .reduce((acc, i) => {
      const odd = expandAroundCenter(i, i);
      const even = expandAroundCenter(i, i + 1);
      return findLongest(acc, findLongest(odd, even));
    }, '');
};

