const Stack = class {
  constructor() {
    this.elements = [];
  }

  push = element => {
    this.elements = [...this.elements, element];
  };

  pop = () => {
    const isEmpty = this.elements.length === 0;
    if (isEmpty) return null;

    const lastIndex = this.elements.length - 1;
    const topElement = this.elements[lastIndex];

    this.elements = this.elements.filter((_, index) => index !== lastIndex);
    return topElement;
  };

  peek = () => this.elements.length === 0 ? null : this.elements[this.elements.length - 1];

  size = () => this.elements.length;

  isEmpty = () => this.elements.length === 0;
};

