const triangleAreaHeron = (a, b, c) => {
  const isPositive = val => val > 0;
  if (![a, b, c].every(isPositive)) return 0;

  const semiPerimeter = (side1, side2, side3) => (side1 + side2 + side3) / 2;
  const s = semiPerimeter(a, b, c);

  const calculateDifference = (val, sVal) => sVal - val;
  const diffA = calculateDifference(a, s);
  const diffB = calculateDifference(b, s);
  const diffC = calculateDifference(c, s);

  if (diffA <= 0 || diffB <= 0 || diffC <= 0) return 0;

  const product = (val1, val2, val3, val4) => val1 * val2 * val3 * val4;
  const areaSquared = product(s, diffA, diffB, diffC);

  const getSquareRoot = num => Math.sqrt(num);
  return getSquareRoot(areaSquared);
};

