const BankAccount = function(initialBalance) {
  this.balance = initialBalance;
};

BankAccount.prototype.deposit = function(amount) {
  const addFunds = (current, val) => current + val;
  this.balance = addFunds(this.balance, amount);
  return this.balance;
};

BankAccount.prototype.withdraw = function(amount) {
  const isSufficient = (current, val) => current >= val;
  const subtractFunds = (current, val) => current - val;

  if (isSufficient(this.balance, amount)) {
    this.balance = subtractFunds(this.balance, amount);
  }
  return this.balance;
};

const createAccount = initialBalance => new BankAccount(initialBalance);

const getBalance = account => account.balance;

const processDeposit = (account, amount) => account.deposit(amount);

const processWithdrawal = (account, amount) => account.withdraw(amount);

const logBalance = account => console.log(`Current balance: ${getBalance(account)}`);

