const isValidISBN10 = isbn => {
  const sanitize = s => s.replace(/[^0-9X]/g, '');
  const toDigits = s => s.split('').map(char => char === 'X' ? 10 : parseInt(char, 10));
  const isValidLength = arr => arr.length === 10;
  const calculateWeightedSum = digits => digits.reduce((sum, digit, i) => sum + digit * (10 - i), 0);
  const isDivisibleBy11 = sum => sum % 11 === 0;

  const sanitizedISBN = sanitize(isbn);
  const digits = toDigits(sanitizedISBN);

  return isValidLength(digits) && isDivisibleBy11(calculateWeightedSum(digits));
};

