const getQuadrant = (x, y) => {
  const isPositive = val => val > 0;
  const isNegative = val => val < 0;
  const isZero = val => val === 0;

  const classifyX = xVal => isPositive(xVal) ? 1 : (isNegative(xVal) ? -1 : 0);
  const classifyY = yVal => isPositive(yVal) ? 1 : (isNegative(yVal) ? -1 : 0);

  const xClass = classifyX(x);
  const yClass = classifyY(y);

  if (isZero(xClass) || isZero(yClass)) {
    return 0;
  }

  const determineQuadrant = (xc, yc) => {
    if (xc > 0 && yc > 0) return 1;
    if (xc < 0 && yc > 0) return 2;
    if (xc < 0 && yc < 0) return 3;
    return 4;
  };

  return determineQuadrant(xClass, yClass);
};

