const groupByParity = numbers => {
  const isEven = num => num % 2 === 0;
  const isOdd = num => num % 2 !== 0;

  const filterNumbers = (arr, predicate) => arr.filter(predicate);

  const evenNumbers = filterNumbers(numbers, isEven);
  const oddNumbers = filterNumbers(numbers, isOdd);

  const createResultObject = (evens, odds) => ({
    even: evens,
    odd: odds
  });

