const timeToMinutes = (timeString) => {
  const [hours, minutes] = timeString.split(':').map(Number);
  return hours * 60 + minutes;
};

const isOverlap = (start1, end1, start2, end2) => {
  return start1 < end2 && start2 < end1;
};

const mapEventToMinutes = (event) => ({
  start: timeToMinutes(event.start),
  end: timeToMinutes(event.end),
});

const hasConflict = (existingEvent, newEvent) => {
  const existing = mapEventToMinutes(existingEvent);
  const newEvt = mapEventToMinutes(newEvent);

  const checkConflict = (e1, e2) => isOverlap(e1.start, e1.end, e2.start, e2.end);

  return checkConflict(existing, newEvt);
};

