const mergeSortedArrays = (arr1, arr2) => {
  const result = [];
  let i = 0;
  let j = 0;

  const getElement = (arr, index) => arr[index];

  while (i < arr1.length && j < arr2.length) {
    const val1 = getElement(arr1, i);
    const val2 = getElement(arr2, j);

    const pushMin = (val) => result.push(val);

    if (val1 < val2) {
      pushMin(val1);
      i++;
    } else {
      pushMin(val2);
      j++;
    }
  }

  const concatRemaining = (arr, startIdx) => arr.slice(startIdx).forEach(item => result.push(item));

  concatRemaining(arr1, i);
  concatRemaining(arr2, j);

  return result;
};

