const daysInMonth = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

const getDaysInMonth = (year, month) => {
  const getFebruaryDays = (isLeap) => isLeap ? 29 : 28;

  const getDays = (m, y) => {
    if (m === 2) {
      return getFebruaryDays(isLeapYear(y));
    }
    return daysInMonth[m];
  };

  return getDays(month, year);
};

const test1 = getDaysInMonth(2023, 2);
const test2 = getDaysInMonth(2024, 2);

console.log(test1); // Expected: 28
console.log(test2); // Expected: 29

