const decodeCaesarCipher = (encryptedText, shift) => {
  const alphabetLength = 26;

  const getCharValue = char => char.charCodeAt(0) - 'a'.charCodeAt(0);
  const getCharFromValue = val => String.fromCharCode(val + 'a'.charCodeAt(0));

  const applyShift = charValue => {
    const shiftedValue = (charValue - shift % alphabetLength + alphabetLength) % alphabetLength;
    return shiftedValue;
  };

  const decodeChar = char => {
    if (char >= 'a' && char <= 'z') {
      const charValue = getCharValue(char);
      const decodedValue = applyShift(charValue);
      return getCharFromValue(decodedValue);
    }
    return char;
  };

  const decodedChars = Array.from(encryptedText).map(decodeChar);
  return decodedChars.join('');
};

