const generateTimesTable = (number, limit) => {
  const range = Array.from({
    length: limit
  }, (_, i) => i + 1);

  const calculateProduct = (num, multiplier) => num * multiplier;

  const formatEntry = (num, multiplier, product) => `${num} * ${multiplier} = ${product}`;

  const processMultiplier = multiplier => {
    const product = calculateProduct(number, multiplier);
    return formatEntry(number, multiplier, product);
  };

  const results = range.map(processMultiplier);

  return results;
};

