const hasAllProperties = (obj, properties) => {
  const checkProperty = (prop) => Object.prototype.hasOwnProperty.call(obj, prop);
  const allExist = properties.every(checkProperty);
  const isNotEmpty = arr => arr.length > 0;
  const hasValidObj = targetObj => typeof targetObj === 'object' && targetObj !== null;
  const finalCheck = (exists, validObj, notEmpty) => exists && validObj && notEmpty;

  return finalCheck(allExist, hasValidObj(obj), isNotEmpty(properties));
};

