const calculateTip = (billTotal, tipPercentage) => {
  const convertPercentageToDecimal = percentage => percentage / 100;
  const calculateRawTip = (total, decimalPercentage) => total * decimalPercentage;
  const roundTip = tip => Math.round(tip * 100) / 100;

  const decimalPercentage = convertPercentageToDecimal(tipPercentage);
  const rawTip = calculateRawTip(billTotal, decimalPercentage);
  const finalTip = roundTip(rawTip);

  const identifyTipType = tip => tip > 10 ? "Generous" : "Standard";
  const logTipType = tip => console.log(`Tip type: ${identifyTipType(tip)}`);

  logTipType(finalTip);
  return finalTip;
};

