  const formatMinutes = () => formatPart(minutes);
  const formatSeconds = () => formatPart(seconds);

  const joinParts = (h, m, s) => `${h}:${m}:${s}`;

  return joinParts(formatHours(), formatMinutes(), formatSeconds());
};

