const getRandomInt = (min, max) => {
  const ceil = Math.ceil;
  const floor = Math.floor;
  const random = Math.random;

  const getMin = x => ceil(x);
  const getMax = x => floor(x);

  const minVal = getMin(min);
  const maxVal = getMax(max);

  const calculateRange = (a, b) => b - a + 1;
  const range = calculateRange(minVal, maxVal);

  const generateRandom = r => floor(r * range);
  const result = generateRandom(random()) + minVal;

  return result;
};

