const countTrailingZeros = n => {
  if (n < 0) return 0;

  let count = 0;
  let powerOfFive = 5;

  const calculateCount = (num, p) => Math.floor(num / p);
  const updatePower = p => p * 5;

  while (true) {
    const currentCount = calculateCount(n, powerOfFive);
    if (currentCount === 0) break;
    count += currentCount;
    powerOfFive = updatePower(powerOfFive);
  }

  return count;
};

