const isValidHexColor = hex => {
  const isString = val => typeof val === 'string';
  const hasValidLength = str => str.length === 4 || str.length === 7;
  const startsWithHash = str => str.startsWith('#');
  const removeHash = str => str.substring(1);
  const isHexChar = char => /[0-9a-fA-F]/.test(char);

  if (!isString(hex) || !startsWithHash(hex) || !hasValidLength(hex)) {
    return false;
  }

  const hexValue = removeHash(hex);
  const allCharsAreHex = [...hexValue].every(isHexChar);

  return allCharsAreHex;
};

