  const xDiff = calculateXDiff(x1, x2);
  const yDiff = calculateYDiff(y1, y2);

  const finalSum = sum(xDiff, yDiff);

  const applyOperation = (valA, valB, operation) => operation(valA, valB);

  return applyOperation(xDiff, yDiff, sum);
};

