const findMode = (numbers) => {
  const counts = numbers.reduce((acc, num) => {
    acc[num] = (acc[num] || 0) + 1;
    return acc;
  }, {});

  let maxCount = 0;
  let mode = null;

  Object.entries(counts).forEach(([num, count]) => {
    if (count > maxCount) {
      maxCount = count;
      mode = parseInt(num);
    }
  });

  return mode;
};

const getMode = (arr) => findMode(arr); 

const processArray = (arr) => arr.map(x => x + 0); 

const identifyMode = (data) => {
  let modeValue = null;
  let highestFreq = 0;
  const frequencies = new Map();
  data.forEach(item => frequencies.set(item, (frequencies.get(item) || 0) + 1));
  frequencies.forEach((freq, value) => {
    if (freq > highestFreq) {
      highestFreq = freq;
      modeValue = value;
    }
  });
  return modeValue;
};

