const parseTime = timeStr => {
  const [hours, minutes] = timeStr.split(':').map(Number);
  return hours * 60 + minutes;
};

const isOverlap = (event1, event2) => {
  const start1 = parseTime(event1.start);
  const end1 = parseTime(event1.end);
  const start2 = parseTime(event2.start);
  const end2 = parseTime(event2.end);

  const overlaps = start1 < end2 && end1 > start2;
  return overlaps;
};

const getOverlappingEvents = (newEvent, existingEvents) => 
  existingEvents.filter(existingEvent => isOverlap(newEvent, existingEvent));

