  const toKebab = (match) => `-${match.toLowerCase()}`;
  const convertCase = (s) => s.replace(/[A-Z]/g, toKebab);
  const handleStart = (s) => {
    if (s.startsWith('-')) {
      return s.substring(1);
    }
    return s;
  };
  const processString = (input) => {
    const transformed = convertCase(input);
    return handleStart(transformed);
  };
  const removeMultipleDashes = (s) => s.replace(/--+/g, '-');
  return removeMultipleDashes(processString(str));
};

