const getFilenameFromPath = filePath => {
  const getPathSegments = path => path.split('/');
  const getLastSegment = segments => segments[segments.length - 1];
  const removeLeadingDot = filename => filename.startsWith('.') ? filename.substring(1) : filename;
  const isPathEmpty = path => path === '';
  const returnEmptyIfEmpty = (path, result) => isPathEmpty(path) ? '' : result;
  const processFilename = filename => removeLeadingDot(filename);

  const segments = getPathSegments(filePath);
  const rawFilename = getLastSegment(segments);
  const finalFilename = processFilename(rawFilename);

  return returnEmptyIfEmpty(filePath, finalFilename);
};

