const isZero = num => num === 0;

const calculateGCD = (a, b) => {
  const euclideanStep = (x, y) => (isZero(y) ? x : euclideanStep(y, x % y));

  const validateInput = (num1, num2) => {
    if (num1 < 0 || num2 < 0 || !Number.isInteger(num1) || !Number.isInteger(num2)) {
      throw new Error("Inputs must be non-negative integers.");
    }
  };

  const getAbsoluteValue = num => Math.abs(num);

  const getLarger = (x, y) => (x > y ? x : y);
  const getSmaller = (x, y) => (x < y ? x : y);

  validateInput(a, b);
  const absA = getAbsoluteValue(a);
  const absB = getAbsoluteValue(b);

  const finalA = getLarger(absA, absB);
  const finalB = getSmaller(absA, absB);

  return euclideanStep(finalA, finalB);
};

