const containsSubarray = (mainArray, subArray) => {
  if (subArray.length === 0) return true;
  if (mainArray.length < subArray.length) return false;

  const arraysEqual = (arr1, arr2) => arr1.length === arr2.length && arr1.every((val, i) => val === arr2[i]);

  const findSubarray = (startIndex) => {
    const sliceEnd = startIndex + subArray.length;
    if (sliceEnd > mainArray.length) return false;
    const currentSlice = mainArray.slice(startIndex, sliceEnd);
    return arraysEqual(currentSlice, subArray);
  };

  for (let i = 0; i <= mainArray.length - subArray.length; i++) {
    if (findSubarray(i)) return true;
  }
  return false;
};

