const generateRectangle = (width, height) => {
  const createRow = len => '*'.repeat(len);

  const createRectangle = (w, h) => {
    const row = createRow(w);
    return Array.from({
      length: h
    }, () => row);
  };

  const mapToString = arr => arr.map(s => s);

  const filterEmpty = arr => arr.filter(s => s.length > 0);

  const transformResult = result => result.length === 1 && result[0].length === 1 ? [result[0]] : result;

  const initialResult = createRectangle(width, height);
  const mappedResult = mapToString(initialResult);
  const filteredResult = filterEmpty(mappedResult);
  return transformResult(filteredResult);
};

