const isPrime = num => {
  if (num <= 1) return false;
  if (num <= 3) return true;
  if (num % 2 === 0 || num % 3 === 0) return false;

  const getDivisor = (currentDivisor, limit) => {
    if (currentDivisor * currentDivisor > limit) return null;
    if (num % currentDivisor === 0) return currentDivisor;
    return getDivisor(currentDivisor + 2, limit);
  };

  const limit = Math.sqrt(num);
  const findSmallestDivisor = initialDivisor => getDivisor(initialDivisor, limit);

  return findSmallestDivisor(5) === null;
};

