const stripProtocol = url => url.replace(/^(https?:\/\/)?(www\.)?/, '');

const splitBySlash = url => url.split('/');

const getFirstElement = arr => arr[0];

const stripQueryParams = domain => domain.split('?')[0];

const cleanDomain = domain => domain.endsWith('/') ? domain.slice(0, -1) : domain;

const extractDomain = url => {
  const processedUrl = stripProtocol(url);
  const parts = splitBySlash(processedUrl);
  const domainWithMaybeQueryParams = getFirstElement(parts);
  const finalDomain = cleanDomain(stripQueryParams(domainWithMaybeQueryParams));
  return finalDomain;
};

