const toKebabCase = str => {
  const isUpperCase = char => char === char.toUpperCase() && char !== char.toLowerCase();
  const insertHyphen = (match, offset, original) => {
    const prevChar = original[offset - 1];
    if (offset > 0 && isUpperCase(match) && !isUpperCase(prevChar)) {
      return `-${match.toLowerCase()}`;
    }
    return match.toLowerCase();
  };
  const replaceUpper = s => s.replace(/[A-Z]/g, insertHyphen);
  const removeLeadingHyphen = s => s.startsWith('-') ? s.substring(1) : s;
  const toLowerCase = s => s.toLowerCase();

  return toLowerCase(removeLeadingHyphen(replaceUpper(str)));
};

