const truncateString = (str, maxLength) => {
  const isTooLong = (s, len) => s.length > len;
  const getEllipsis = () => '...';
  const getTruncatedPart = (s, len) => s.slice(0, len - getEllipsis().length);
  const appendEllipsis = (s) => s + getEllipsis();

  return isTooLong(str, maxLength)
    ? (() => {
        const truncated = getTruncatedPart(str, maxLength);
        return appendEllipsis(truncated);
      })()
    : str;
};

